// ==================================================
// Validated Investigation Plan Input
//
// Simulates the canonical validated output produced
// by:
//
// 04 - Investigation Planner
// ==================================================

return [
  {
    json: {
      plan_version: "1.0",

      alert_id: "ALERT-0001",

      objective:
        "Verify available authentication and endpoint evidence related to the identity alert.",

      investigation_steps: [
        {
          step_id: "step-1",

          priority: "high",

          purpose:
            "Collect historical sign-in data to assess unusual authentication patterns.",

          tool:
            "get_signins",

          parameters: {
            user:
              "john.doe@example.com"
          },

          evidence_target:
            "Historical authentication events for the observed user."
        },

        {
          step_id: "step-2",

          priority: "medium",

          purpose:
            "Collect endpoint activity associated with the observed host.",

          tool:
            "get_endpoint_activity",

          parameters: {
            host:
              "WIN11-LAPTOP-01"
          },

          evidence_target:
            "Endpoint security activity for the observed host."
        }
      ]
    }
  }
];

// ==================================================
// Investigation Step Expander
//
// Converts one canonical investigation plan into
// one n8n item per investigation step.
// ==================================================

const plan = $json;


// --------------------------------------------------
// 1. Validate plan
// --------------------------------------------------

if (
  typeof plan !== "object" ||
  plan === null ||
  Array.isArray(plan)
) {
  throw new Error(
    "Investigation Step Expander received an invalid plan"
  );
}


if (
  typeof plan.alert_id !== "string" ||
  plan.alert_id.trim() === ""
) {
  throw new Error(
    "Investigation Step Expander requires alert_id"
  );
}


if (
  !Array.isArray(
    plan.investigation_steps
  )
) {
  throw new Error(
    "Investigation Step Expander requires investigation_steps"
  );
}


if (
  plan.investigation_steps.length === 0
) {
  throw new Error(
    "Investigation Step Expander received an empty investigation plan"
  );
}


// --------------------------------------------------
// 2. Expand steps
// --------------------------------------------------

const items = [];

for (
  let index = 0;
  index < plan.investigation_steps.length;
  index++
) {

  const step =
    plan.investigation_steps[index];


  if (
    typeof step !== "object" ||
    step === null ||
    Array.isArray(step)
  ) {
    throw new Error(
      `investigation_steps[${index}] must be an object`
    );
  }


  if (
    typeof step.step_id !== "string" ||
    step.step_id.trim() === ""
  ) {
    throw new Error(
      `investigation_steps[${index}].step_id is required`
    );
  }


  if (
    typeof step.tool !== "string" ||
    step.tool.trim() === ""
  ) {
    throw new Error(
      `investigation_steps[${index}].tool is required`
    );
  }


  if (
    typeof step.parameters !== "object" ||
    step.parameters === null ||
    Array.isArray(step.parameters)
  ) {
    throw new Error(
      `investigation_steps[${index}].parameters must be an object`
    );
  }


  // ----------------------------------------------
  // Canonical tool request
  // ----------------------------------------------

  items.push({
    json: {
      request_version:
        "1.0",

      alert_id:
        plan.alert_id,

      step_id:
        step.step_id,

      tool:
        step.tool,

      parameters:
        step.parameters,

      context: {
        priority:
          step.priority || null,

        purpose:
          step.purpose || null,

        evidence_target:
          step.evidence_target || null
      }
    }
  });
}


// --------------------------------------------------
// 3. Return one n8n item per investigation step
// --------------------------------------------------

return items;

// ==================================================
// Investigation Evidence Aggregator
//
// Aggregates canonical tool results produced by the
// Tool Router into one investigation evidence object.
//
// Input:
// multiple n8n items
//
// Output:
// one canonical investigation evidence object
// ==================================================

const items = $input.all();


// --------------------------------------------------
// 1. Retrieve original validated plan
// --------------------------------------------------

const plan =
  $("Validated Investigation Plan Input").first().json;


// --------------------------------------------------
// 2. Basic validation
// --------------------------------------------------

if (
  !plan ||
  typeof plan !== "object" ||
  Array.isArray(plan)
) {
  throw new Error(
    "Investigation Evidence Aggregator could not retrieve the validated investigation plan"
  );
}


if (
  typeof plan.alert_id !== "string" ||
  plan.alert_id.trim() === ""
) {
  throw new Error(
    "Investigation Evidence Aggregator requires alert_id"
  );
}


// --------------------------------------------------
// 3. Aggregate tool executions
// --------------------------------------------------

const toolExecutions = [];

let successfulTools = 0;
let partialTools = 0;
let failedTools = 0;
let rejectedTools = 0;

let totalEvidenceItems = 0;


// --------------------------------------------------
// 4. Process each Tool Router result
// --------------------------------------------------

for (
  let index = 0;
  index < items.length;
  index++
) {

  const result =
    items[index].json;


  // ----------------------------------------------
  // Rejected tool request
  // ----------------------------------------------

  if (
    result?.status === "rejected"
  ) {

    rejectedTools++;

    toolExecutions.push({
      execution_index:
        index + 1,

      tool:
        result.request?.tool || null,

      status:
        "rejected",

      query:
        result.request?.parameters || null,

      result_count:
        0,

      evidence:
        [],

      errors:
        Array.isArray(result.errors)
          ? result.errors
          : []
    });

    continue;
  }


  // ----------------------------------------------
  // Canonical tool result validation
  // ----------------------------------------------

  if (
    !result ||
    typeof result !== "object" ||
    Array.isArray(result)
  ) {
    throw new Error(
      `Tool result at index ${index} is invalid`
    );
  }


  if (
    typeof result.tool !== "string" ||
    result.tool.trim() === ""
  ) {
    throw new Error(
      `Tool result at index ${index} does not contain a valid tool name`
    );
  }


  if (
    !Array.isArray(result.evidence)
  ) {
    throw new Error(
      `Tool result '${result.tool}' does not contain an evidence array`
    );
  }


  // ----------------------------------------------
  // Counters
  // ----------------------------------------------

  switch (result.status) {

    case "success":
      successfulTools++;
      break;

    case "partial":
      partialTools++;
      break;

    case "error":
      failedTools++;
      break;

    default:
      throw new Error(
        `Tool result '${result.tool}' contains unsupported status '${result.status}'`
      );
  }


  totalEvidenceItems +=
    result.evidence.length;


  // ----------------------------------------------
  // Store canonical execution
  // ----------------------------------------------

  toolExecutions.push({
    execution_index:
      index + 1,

    tool:
      result.tool,

    tool_version:
      result.tool_version || null,

    status:
      result.status,

    query:
      result.query || null,

    result_count:
      result.result_count ?? result.evidence.length,

    evidence:
      result.evidence,

    error:
      result.error || null
  });
}


// --------------------------------------------------
// 5. Overall investigation status
// --------------------------------------------------

let investigationStatus =
  "success";


if (
  failedTools > 0 ||
  rejectedTools > 0 ||
  partialTools > 0
) {

  if (
    successfulTools > 0 ||
    partialTools > 0
  ) {
    investigationStatus =
      "partial";
  } else {
    investigationStatus =
      "failed";
  }
}


// --------------------------------------------------
// 6. Canonical investigation evidence
// --------------------------------------------------

const aggregatedEvidence = {

  evidence_bundle_version:
    "1.0",

  alert_id:
    plan.alert_id,

  investigation_objective:
    plan.objective || null,

  status:
    investigationStatus,

  execution_summary: {
    requested_steps:
      Array.isArray(
        plan.investigation_steps
      )
        ? plan.investigation_steps.length
        : items.length,

    executed_tools:
      items.length,

    successful_tools:
      successfulTools,

    partial_tools:
      partialTools,

    failed_tools:
      failedTools,

    rejected_tools:
      rejectedTools,

    total_evidence_items:
      totalEvidenceItems
  },

  tool_executions:
    toolExecutions
};


// --------------------------------------------------
// 7. Return one aggregated item
// --------------------------------------------------

return [
  {
    json:
      aggregatedEvidence
  }
];
